import { Entity } from '../../Engine/Entity';
import type { TurretConfig } from '../Config/TurretConfig';

export class Turret extends Entity {
    readonly kind = 'turret';

    /** 所属 Boss 的 id */
    public ownerId = 0;

    /** 配置（只读） */
    public config: TurretConfig = null!;

    public hp = 0;
    public maxHp = 0;
    public collisionRadius = 14;

    /** 当前炮口朝向（度）。TurretAimSystem 写，FireSystem 读 */
    public aimAngle = 0;

    /** oscillate 模式相位（弧度） */
    public oscPhase = 0;

    /** 开火冷却累积（秒）。FireSystem 写 */
    public cooldownTimer = 0;

    /** 当前是否被编排允许开火。TurretScheduleSystem 写 */
    public active = false;
}